import json
def f(g):
    H,W=len(g),len(g[0])
    from collections import Counter
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    out=[r[:] for r in g]
    seen=set()
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg and (r,c) not in seen:
                col=g[r][c]; st=[(r,c)]; cells=[]
                while st:
                    x,y=st.pop()
                    if (x,y) in seen or g[x][y]!=col: continue
                    seen.add((x,y)); cells.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=x+dx,y+dy
                        if 0<=nx<H and 0<=ny<W and (nx,ny) not in seen and g[nx][ny]==col:
                            st.append((nx,ny))
                rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                inter=[(i,j) for i in range(r0+1,r1) for j in range(c0+1,c1) if g[i][j]!=col]
                if inter:
                    fill=2 if len(inter)%2==0 else 7
                    for i,j in inter: out[i][j]=fill
    return out
